INSERT IGNORE INTO smart_mokta_rfq (mr_uid, mr_inid, mr_author, mr_cat, mr_region_tag, mr_dates, mr_pax_type, mr_title, mr_memo, mr_specs_json, mr_bid_cnt, mr_view_yn, mr_rdate) VALUES (1, '', '김*서', '단독투어', '고비', '8월 15일 ~ 8월 19일 (4박 5일)', '단독투어 · 직장인 친구 4명 확정', '광복절 연휴 친구 4명 고비사막 4박5일 단독투어 (온수 샤워 캠프 희망)', '대한항공 오후 도착 항공권 발권 완료했습니다. 차강소브락·홍고린엘스·바양작 코스로 희망하며, 전 일정 샤워 가능한 깔끔한 게르와 신형 스타렉스 조건으로 비교해보고 싶습니다.', '["4명 단독차량","신형 스타렉스 희망","샤워 가능 캠프 필수","현지 추가금 0원 조건"]', 3, 'Y', NOW());
INSERT IGNORE INTO smart_mokta_rfq (mr_uid, mr_inid, mr_author, mr_cat, mr_region_tag, mr_dates, mr_pax_type, mr_title, mr_memo, mr_specs_json, mr_bid_cnt, mr_view_yn, mr_rdate) VALUES (2, '', '박*현', '단독투어', '홉스골', '7월 28일 ~ 8월 02일 (5박 6일)', '가족 단독투어 · 부모님 동반 5명', '부모님 칠순 기념 여름 홉스골 호수 + 온천 편안한 가족 단독투어 문의', '60대 부모님 두 분 포함 성인 5명 가족여행입니다. 비포장 이동이 너무 힘들지 않게 국내선 왕복 또는 리무진 벤 차량과 깨끗한 호숫가 숙소 위주로 제안 부탁드립니다.', '["부모님 동반 5인","홉스골+온천 힐링","개별 욕실 리조트 선호","한식·특식 케어"]', 2, 'Y', NOW());
INSERT IGNORE INTO smart_mokta_rfq (mr_uid, mr_inid, mr_author, mr_cat, mr_region_tag, mr_dates, mr_pax_type, mr_title, mr_memo, mr_specs_json, mr_bid_cnt, mr_view_yn, mr_rdate) VALUES (3, '', '이*진', '동행조인', '고비', '9월 04일 ~ 9월 07일 (3박 4일)', '동행조인 · 20대 커플 2명 확정 (추가동행 희망)', '9월 초 사막+쳉헤르 노천온천+별밤 스냅 3박4일 조인 가능한 투어 찾아요', '연차 2개 쓰고 가는 커플 2명입니다! 단독으로 가기엔 비용이 부담되어 총 4~6명 조인 가능한 팀이나 사막·온천 알짜 코스 제안 기다립니다.', '["2명 확정 (조인희망)","미니사막+쳉헤르온천","별밤 사진촬영 선호","1/N 각자결제 희망"]', 2, 'Y', NOW());
INSERT IGNORE INTO smart_mokta_rfq (mr_uid, mr_inid, mr_author, mr_cat, mr_region_tag, mr_dates, mr_pax_type, mr_title, mr_memo, mr_specs_json, mr_bid_cnt, mr_view_yn, mr_rdate) VALUES (4, '', '최*우', '동행조인', '홉스골', '8월 07일 ~ 8월 10일 (3박 4일)', '1인 혼자 출발 · 출발확정 조인방 희망', '혼자 떠나는 첫 몽골! 동행 못 구해도 무조건 출발 확정되는 3박4일 추천해주세요', '휴가 날짜가 8/7~8/10으로 고정이라 모객 미달로 취소되지 않는 100% 출발확정 조인 투어를 찾고 있습니다.', '["1인 출발확정 필수","3박4일 중부·테를지","유심·식사 올인원 선호"]', 1, 'Y', NOW());
